const NAME_SUFFIXES = new Set(["jr","jr.","sr","sr.","ii","iii","iv","v"]);

export function lastNameOf(name) {
    if (!name) return '';
    const parts = name.trim().split(/\s+/);
    while (parts.length > 1 && NAME_SUFFIXES.has(parts[parts.length - 1].toLowerCase().replace(/\.$/, ''))) {
      parts.pop();
    }
    return parts[parts.length - 1] || '';
  }

export function levenshteinDist(a, b) {
    const m = a.length, n = b.length;
    if (!m) return n;
    if (!n) return m;
    let prev = Array.from({ length: n + 1 }, (_, j) => j);
    for (let i = 1; i <= m; i++) {
      const cur = [i];
      for (let j = 1; j <= n; j++) {
        cur[j] = a[i - 1] === b[j - 1]
          ? prev[j - 1]
          : 1 + Math.min(prev[j - 1], prev[j], cur[j - 1]);
      }
      prev = cur;
    }
    return prev[n];
  }

export function nameTokens(name) {
    return String(name || '')
      .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z\s]/g, '').trim().split(/\s+/).filter(Boolean);
  }

export function namesLikelyMatch(nameA, nameB) {
    const ta = nameTokens(nameA), tb = nameTokens(nameB);
    if (!ta.length || !tb.length) return false;
    for (const wa of ta) {
      if (wa.length < 3) continue;
      for (const wb of tb) {
        if (wb.length < 3) continue;
        if (wa === wb) return true;
        const allowedDist = Math.max(wa.length, wb.length) >= 7 ? 2 : 1;
        if (levenshteinDist(wa, wb) <= allowedDist) return true;
      }
    }
    return false;
  }

export function buildBoutPairings(evtFights) {
    const pairings = [];
    (evtFights || []).forEach(f => {
      if (f.f1 && f.f2) {
        pairings.push([f.f1, f.f2]);
      }
    });
    return pairings;
  }

export function canonOddsName(n) {
    return (typeof NAME_ALIASES !== 'undefined' && NAME_ALIASES[String(n || '').toLowerCase()]) || n;
  }

export function isScheduledBout(pairings, full1, full2) {
    full1 = canonOddsName(full1); full2 = canonOddsName(full2);
    const n1 = lastNameOf(full1).toLowerCase(), n2 = lastNameOf(full2).toLowerCase();
    return pairings.some(([pf1, pf2]) => {
      const a = lastNameOf(pf1).toLowerCase(), b = lastNameOf(pf2).toLowerCase();
      if ((a === n1 && b === n2) || (a === n2 && b === n1)) return true;
      // Fuzzy fallback — see namesLikelyMatch() above.
      return (namesLikelyMatch(pf1, full1) && namesLikelyMatch(pf2, full2)) ||
             (namesLikelyMatch(pf1, full2) && namesLikelyMatch(pf2, full1));
    });
  }

export function pairKey(n1, n2) {
    return [lastNameOf(n1).toLowerCase(), lastNameOf(n2).toLowerCase()].sort().join('|');
  }

export function findManualProps(fight) {
    return MANUAL_PROP_ODDS[pairKey(fight.home_team, fight.away_team)] || null;
  }

export function manualSideFor(fight, who) {
    const homeLast = lastNameOf(fight.home_team).toLowerCase();
    const awayLast = lastNameOf(fight.away_team).toLowerCase();
    const homeIsF1 = homeLast === [homeLast, awayLast].sort()[0];
    if (who === 'away') return homeIsF1 ? 'f2' : 'f1';
    return homeIsF1 ? 'f1' : 'f2';
  }

export function oddsAvatarInitials(name) {
    const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
    if (!parts.length) return '?';
    const a = parts[0][0] || '';
    const b = parts.length > 1 ? (parts[parts.length - 1][0] || '') : '';
    return (a + b).toUpperCase();
  }
